async function click(text,scope=document){const b=[...scope.querySelectorAll('button')].find(x=>x.textContent.trim()===text);assert(b,'Missing button '+text);await act(async()=>b.click());await settle();}
async function select(label,value){const l=[...document.querySelectorAll('dialog label')].find(l=>l.childNodes[0]?.textContent===label),el=l?.querySelector('select');assert(el,'Missing select '+label);await act(async()=>{el.value=value;el.dispatchEvent(new dom.window.Event('change',{bubbles:true}))});}
async function changeControl(el,value){assert(el);await act(async()=>{Object.getOwnPropertyDescriptor(el.tagName==='SELECT'?dom.window.HTMLSelectElement.prototype:dom.window.HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new dom.window.Event(el.tagName==='SELECT'?'change':'input',{bubbles:true}))});}
async function popupInteractions(dialog){
 assert(dialog?.open,'Popup must start open');
 const fields=[...dialog.querySelectorAll('input,select,textarea')].map(el=>({el,value:el.value}));
 const field=fields.find(({el})=>el.type!=='file')?.el||dialog.querySelector('h2');
 await act(async()=>{
  for(const type of ['mousemove','mouseover','mouseout','mouseenter','mouseleave']){
   field.dispatchEvent(new dom.window.MouseEvent(type,{bubbles:true,relatedTarget:dialog}));
   dialog.dispatchEvent(new dom.window.MouseEvent(type,{bubbles:true,relatedTarget:document.body}));
  }
  field.focus();field.blur();
  // A drag/select or scrollbar interaction may end with a click targeted at dialog.
  field.dispatchEvent(new dom.window.MouseEvent('mousedown',{bubbles:true}));
  dialog.dispatchEvent(new dom.window.MouseEvent('mouseup',{bubbles:true}));
  dialog.dispatchEvent(new dom.window.MouseEvent('click',{bubbles:true}));
  for(const type of ['pointerdown','pointermove','pointerout','pointerup','touchstart','touchmove','touchend'])dialog.dispatchEvent(new dom.window.Event(type,{bubbles:true}));
  dialog.dispatchEvent(new dom.window.Event('scroll'));
 });
 await settle();
 assert(dialog.isConnected&&dialog.open,'Moving, dragging, scrolling or tapping outside must not dismiss a popup');
 for(const {el,value}of fields){assert(el.isConnected,'Popup fields must not remount');assert.equal(el.value,value,'Unsaved popup values must remain');}
}
